/** Clinician rating entry (blinded reference standard for validation studies). */
import { useState } from 'preact/hooks';
import { MOVEMENT_TASKS, sunnybrookComposite, type MovementTaskId } from '../../core';
import { actions, useApp } from '../../data/store';
import type { SunnybrookItems } from '../../data/types';
import { AppBar, Notice, Segmented } from '../components/common';
import { TASK_LABEL, fmtDateTime } from '../labels';
import { back } from '../router';

const HB_OPTS = ['I', 'II', 'III', 'IV', 'V', 'VI'].map((l, i) => ({ value: String(i + 1), label: l }));
const nums = (a: number, b: number) => Array.from({ length: b - a + 1 }, (_, k) => ({ value: String(a + k), label: String(a + k) }));

export function Rate({ id }: { id: string }) {
  const { sessions } = useApp();
  const s = sessions.find((x) => x.id === id);
  const [rater, setRater] = useState('');
  const [hb, setHb] = useState<string>('');
  const [useSb, setUseSb] = useState(true);
  const [sb, setSb] = useState<SunnybrookItems>({
    rest: { eye: 0, cheek: 0, mouth: 0 },
    voluntary: { brow: 5, eyeClose: 5, smile: 5, snarl: 5, pucker: 5 },
    synkinesis: { brow: 0, eyeClose: 0, smile: 0, snarl: 0, pucker: 0 },
  });
  const [note, setNote] = useState('');
  if (!s) return null;
  const composite = sunnybrookComposite(sb);
  const setVol = (t: MovementTaskId, v: string) => setSb({ ...sb, voluntary: { ...sb.voluntary, [t]: Number(v) } });
  const setSyn = (t: MovementTaskId, v: string) => setSb({ ...sb, synkinesis: { ...sb.synkinesis, [t]: Number(v) } });
  const canSave = rater.trim().length > 0 && (hb !== '' || useSb);

  return (
    <>
      <AppBar title="임상가 평가 입력" sub={fmtDateTime(s.createdAt)} onBack />
      <main class="main">
        <div class="card warn tight">
          <Notice tone="warn">
            <span class="small">
              맹검 평가: 앱의 추정 결과를 보기 전에, 같은 방문에서 직접 관찰한 소견으로 입력하세요. 입력 후에는 수정할 수 없고 새 평가로만
              추가됩니다.
            </span>
          </Notice>
        </div>
        <div class="card">
          <label class="field">
            <span>평가자 코드 (이니셜 또는 연구 ID)</span>
            <input class="input" value={rater} maxLength={16} onInput={(e) => setRater((e.target as HTMLInputElement).value)} />
          </label>
          <div class="field">
            <span>House–Brackmann 등급</span>
            <Segmented label="House–Brackmann" value={hb} onChange={setHb} options={HB_OPTS} />
          </div>
        </div>

        <label class="check">
          <input type="checkbox" checked={useSb} onChange={(e) => setUseSb((e.target as HTMLInputElement).checked)} />
          <span>Sunnybrook 전체 항목 입력</span>
        </label>

        {useSb && (
          <>
            <div class="card">
              <h3>안정 시 대칭 (×5)</h3>
              <div class="field">
                <span>눈 (안검열) — 0 정상 · 1 좁음/넓음/수술</span>
                <Segmented
                  label="안정 눈"
                  value={String(sb.rest.eye)}
                  onChange={(v) => setSb({ ...sb, rest: { ...sb.rest, eye: Number(v) } })}
                  options={nums(0, 1)}
                />
              </div>
              <div class="field">
                <span>볼 (비순구) — 0 정상 · 1 덜/더 뚜렷 · 2 없음</span>
                <Segmented
                  label="안정 볼"
                  value={String(sb.rest.cheek)}
                  onChange={(v) => setSb({ ...sb, rest: { ...sb.rest, cheek: Number(v) } })}
                  options={nums(0, 2)}
                />
              </div>
              <div class="field">
                <span>입 — 0 정상 · 1 처짐/당겨짐</span>
                <Segmented
                  label="안정 입"
                  value={String(sb.rest.mouth)}
                  onChange={(v) => setSb({ ...sb, rest: { ...sb.rest, mouth: Number(v) } })}
                  options={nums(0, 1)}
                />
              </div>
            </div>
            <div class="card">
              <h3>수의 운동 대칭 (1–5, ×4)</h3>
              <p class="xsmall muted">1 움직임 없음 · 2 약간 시작 · 3 부분 · 4 거의 완전 · 5 완전</p>
              {MOVEMENT_TASKS.map((t) => (
                <div class="field">
                  <span>{TASK_LABEL[t]}</span>
                  <Segmented
                    label={`수의운동 ${TASK_LABEL[t]}`}
                    value={String(sb.voluntary[t])}
                    onChange={(v) => setVol(t, v)}
                    options={nums(1, 5)}
                  />
                </div>
              ))}
            </div>
            <div class="card">
              <h3>동반운동 (0–3)</h3>
              <p class="xsmall muted">0 없음 · 1 경도 · 2 중등도 · 3 중증</p>
              {MOVEMENT_TASKS.map((t) => (
                <div class="field">
                  <span>{TASK_LABEL[t]}</span>
                  <Segmented
                    label={`동반운동 ${TASK_LABEL[t]}`}
                    value={String(sb.synkinesis[t])}
                    onChange={(v) => setSyn(t, v)}
                    options={nums(0, 3)}
                  />
                </div>
              ))}
            </div>
            <div class="card accent tight">
              <div class="row between">
                <span>Sunnybrook 종합 점수</span>
                <b class="tabular" style={{ fontSize: '22px' }}>
                  {composite}
                </b>
              </div>
            </div>
          </>
        )}

        <label class="field">
          <span>메모 (선택)</span>
          <textarea class="input" rows={2} value={note} maxLength={500} onInput={(e) => setNote((e.target as HTMLTextAreaElement).value)} />
        </label>
        <button
          class="btn primary block"
          disabled={!canSave}
          onClick={async () => {
            await actions.addRating({
              sessionId: s.id,
              raterId: rater.trim(),
              houseBrackmann: hb ? Number(hb) : null,
              sunnybrook: useSb ? sb : null,
              sunnybrookComposite: useSb ? composite : null,
              note,
            });
            back(`/session/${s.id}`);
          }}
        >
          저장
        </button>
      </main>
    </>
  );
}
